mapper.select:
SELECT a.id AS `id`, c.merchant_id AS `merchantId`, c.id AS `channelId`, b.username AS `username`, a.finish_time AS `finishTime`, e.round_id AS `bureauNumber`, a.bet_type AS `betType`, a.bet AS `bet`, a.tag AS `tag`, a.game_code AS `gameCode`, a.bet_time AS `betTime`, a.settlement_multiple AS `settlementMultiple`, e.billing_type AS `billingType`, a.user_id AS `userId`, e.result AS `result`, a.pay_out AS `payOut` FROM lms_coin_record a LEFT JOIN ums_user b ON a.user_id = b.id LEFT JOIN mms_channel c ON a.channel_id = c.id AND c.deleted_at IS NULL LEFT JOIN lms_game_record e ON a.channel_id = e.channel_id AND a.round_id = e.round_id WHERE a.user_id >= 10000
AND a.channel_id = #{channelId}
AND a.channel_id IN
#{cid}
AND c.merchant_id = #{merchantId}
AND b.username = #{username}
AND a.tag = #{tag}
AND e.round_id = #{bureauNumber}
AND a.id = #{id}
AND a.expand_time BETWEEN #{startAt} AND #{endAt}
ORDER BY
a.id a.user_id a.channel_id a.bet a.pay_out a.bet_type a.finish_time a.settlement_multiple a.expand_time
ASC DESC
ORDER BY a.expand_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM lms_coin_record a
LEFT JOIN ums_user b ON a.user_id = b.id
LEFT JOIN mms_channel c ON a.channel_id = c.id AND c.deleted_at IS NULL
LEFT JOIN lms_game_record e ON a.channel_id = e.channel_id AND a.round_id = e.round_id
WHERE a.user_id >= 10000

    AND a.channel_id = #{channelId}


    AND a.channel_id IN

        #{cid}



    AND c.merchant_id = #{merchantId}


    AND b.username = #{username}


    AND a.tag = #{tag}


    AND e.round_id = #{bureauNumber}


    AND a.id = #{id}


    AND a.expand_time BETWEEN #{startAt} AND #{endAt}

SELECT a.tag, IFNULL(SUM(a.bet), 0) AS bets, IFNULL(SUM(IF(a.pay_out > 0, a.pay_out, 0)), 0) AS payOut, IFNULL(SUM(a.bet - a.pay_out), 0) AS winLows FROM lms_coin_record a LEFT JOIN ums_user b ON a.user_id = b.id WHERE a.user_id >= 10000 AND a.tag = #{tag}
AND a.channel_id IN
#{channelId}
GROUP BY a.tag

SELECT a.tag, IFNULL(SUM(a.bet), 0) AS bets, IFNULL(SUM(IF(a.pay_out > 0, a.pay_out, 0)), 0) AS payOut, IFNULL(SUM(a.bet - a.pay_out), 0) AS winLows FROM lms_coin_record a LEFT JOIN ums_user b ON a.user_id = b.id WHERE a.user_id >= 10000 AND a.tag = #{tag} AND a.created_at >= #{start} AND a.created_at < #{end}
AND a.channel_id IN
#{channelId}
GROUP BY a.tag

SELECT COUNT(DISTINCT a.user_id)
FROM lms_coin_record a
WHERE a.user_id >= 10000
AND a.tag = #{tag}

    AND a.channel_id IN

        #{channelId}

SELECT COUNT(DISTINCT a.user_id)
FROM lms_coin_record a
WHERE a.user_id >= 10000
AND a.tag = #{tag}
AND a.created_at >= #{start}
AND a.created_at < #{end}

    AND a.channel_id IN

        #{channelId}

SELECT DATE_FORMAT(a.created_at, '%Y-%m-%d') AS dayTime, a.channel_id, a.game_code AS gameCode, COUNT(DISTINCT a.user_id) AS betsNumber, IFNULL(SUM(a.bet), 0) AS bets, IFNULL(SUM(a.pay_out), 0) AS payOut, IFNULL(SUM(a.pay_out - a.bet), 0) AS playerWl, IFNULL(SUM(a.bet - a.pay_out), 0) AS platformWl FROM lms_coin_record a WHERE a.channel_id = #{channelId}
AND a.tag = #{tag}
AND a.game_code IS NULL AND a.game_code = #{gameCode}
AND a.created_at BETWEEN #{startAt} AND #{endAt}
GROUP BY DATE_FORMAT(a.created_at, '%Y-%m-%d'), a.channel_id, a.game_code ORDER BY dayTime DESC LIMIT #{offsetRows}, #{limit}

SELECT COUNT(1)
FROM (
    SELECT DATE_FORMAT(a.created_at, '%Y-%m-%d') AS dayTime, a.channel_id
    FROM lms_coin_record a
    WHERE a.channel_id = #{channelId}

        AND a.tag = #{tag}


        AND a.game_code IS NULL
        AND a.game_code = #{gameCode}


        AND a.created_at BETWEEN #{startAt} AND #{endAt}

    GROUP BY DATE_FORMAT(a.created_at, '%Y-%m-%d'), a.channel_id, a.game_code
) t

SELECT
    IFNULL(SUM(a.bet), 0) AS bets,
    IFNULL(SUM(a.pay_out), 0) AS payOut,
    IFNULL(SUM(a.pay_out - a.bet), 0) AS playerWl,
    IFNULL(SUM(a.bet - a.pay_out), 0) AS platformWl
FROM lms_coin_record a
WHERE a.channel_id = #{channelId}

    AND a.tag = #{tag}


    AND a.game_code IS NULL
    AND a.game_code = #{gameCode}


    AND a.created_at BETWEEN #{startAt} AND #{endAt}

SELECT COUNT(DISTINCT a.user_id)
FROM lms_coin_record a
WHERE a.channel_id = #{channelId}

    AND a.tag = #{tag}


    AND a.game_code IS NULL
    AND a.game_code = #{gameCode}


    AND a.created_at BETWEEN #{startAt} AND #{endAt}

SELECT COUNT(DISTINCT a.user_id)
FROM lms_coin_record a
LEFT JOIN mms_channel c ON c.id = a.channel_id AND c.deleted_at IS NULL
WHERE a.expand_time BETWEEN #{startTime} AND #{endTime}
  AND c.id = #{channelId}
  AND a.user_id >= 10000
  AND a.tag = #{tag}
  AND ((#{gameCode} = '__legacy__' AND a.game_code IS NULL) OR a.game_code = #{gameCode})

SELECT COUNT(DISTINCT a.user_id)
FROM lms_coin_record a
LEFT JOIN ums_user b ON a.user_id = b.id
LEFT JOIN mms_channel c ON b.channel_id = c.id AND c.deleted_at IS NULL
LEFT JOIN mms_merchant d ON c.merchant_id = d.id AND d.deleted_at IS NULL
WHERE a.created_at BETWEEN #{startTime} AND #{endTime}
  AND d.id = #{merchantId}
  AND a.user_id >= 10000
  AND a.tag = #{tag}
